<?php
namespace App\Services;
use App\Models\CashDay;use App\Models\Order;use App\Models\Purchase;
class CashReportService{
 public function summary(int$branchId,$date):array{$orders=Order::where('branch_id',$branchId)->whereDate('order_date',$date)->get();$ids=$orders->pluck('id');$payments=\App\Models\OrderPayment::whereIn('order_id',$ids)->selectRaw('method, SUM(amount) total')->groupBy('method')->pluck('total','method');$cashPurchases=(float)Purchase::where('branch_id',$branchId)->whereDate('purchased_at',$date)->where('payment_source','cash')->sum('total');$day=CashDay::with('movements')->where('branch_id',$branchId)->whereDate('date',$date)->first();$income=(float)($day?->movements->where('type','income')->sum('amount')??0);$expense=(float)($day?->movements->where('type','expense')->sum('amount')??0);$cash=(float)($payments['cash']??0);return['date'=>(string)$date,'orders'=>$orders->whereNotIn('status',['draft','pending_payment','cancelled'])->count(),'gross_sales'=>(float)$orders->whereNotIn('status',['draft','pending_payment','cancelled'])->where('courtesy',false)->sum('total'),'cash'=>$cash,'transfer'=>(float)($payments['transfer']??0),'courtesy'=>(float)$orders->where('courtesy',true)->sum('total'),'discounts'=>(float)$orders->sum('discount'),'cancelled'=>$orders->where('status','cancelled')->count(),'cash_purchases'=>$cashPurchases,'other_income'=>$income,'other_expenses'=>$expense,'expected_cash'=>(float)($day?->opening_amount??0)+$cash+$income-$expense-$cashPurchases];}
}
